let RT='inicio',bus={q:'',cat:'',sub:'',tiendas:[],max:0,ofertas:false,orden:'vendidos'},tabsCB={},stTab={},stFil={sub:'',q:''},pnTab={};
function go(h){if(location.hash.slice(1)===h){render();scrollTo(0,0)}else location.hash=h}

function render(){
 const r=(location.hash||'#inicio').slice(1)||'inicio';RT=r;
 const ses=S.session;
 const isPanel=r==='panel'||r.indexOf('panel-')===0;
 document.body.classList.toggle('mode-panel',isPanel);
 closeDept();
 if(isPanel){
  if(!ses||ses.rol==='cliente'){history.replaceState(null,'','#inicio');RT='inicio';$('#app').innerHTML=vHome();afterHome();openLogin('negocio');}
  else $('#app').innerHTML=vPanel(r);
 }else if(r.indexOf('cuenta')===0){
  if(!ses||ses.rol!=='cliente'){history.replaceState(null,'','#inicio');RT='inicio';$('#app').innerHTML=vHome();afterHome();openLogin('cliente');}
  else $('#app').innerHTML=vCuenta(r);
 }else if(r.indexOf('t-')===0&&T(r.slice(2))){$('#app').innerHTML=vTienda(r.slice(2))}
 else if(r==='buscar'||r.indexOf('c-')===0){
  if(r.indexOf('c-')===0){const c=r.slice(2);bus={q:'',cat:c==='ofertas'?'':c,sub:'',tiendas:[],max:0,ofertas:c==='ofertas',orden:'vendidos'};history.replaceState(null,'','#buscar');RT='buscar'}
  $('#app').innerHTML=vBuscar();
 }else{$('#app').innerHTML=vHome();afterHome()}
 paint();updHeader();
}

