function artP(p,big){const t=T(p.t),pr=precio(p);const foto=pr.promo&&pr.promo.foto;
 return '<span class="art-p'+(tclaro(t)?' claro':'')+'" style="--c:'+tc(t)+'">'+(foto?'<img src="'+foto+'" alt="">':'')+ic(p.i)+(pr.old&&!big?'<span class="star-off">-'+Math.round((1-pr.p/pr.old)*100)+'%</span>':(p.nuevo&&!big?'<span class="tag-new">NUEVO</span>':''))+(!t.abierto&&!big?'<span class="cerrado-tag">Cerrado ahora · abre '+t.horario.split('–')[0].trim()+'</span>':'')+'</span>';}
function card(p,deal){
 const t=T(p.t),pr=precio(p),fav=S.user.favP.includes(p.id)&&S.session&&S.session.rol==='cliente';
 const off=!p.disp||!t.abierto;
 let sold='';if(deal&&pr.promo){const pc=Math.min(100,Math.round(pr.promo.vend/pr.promo.cupo*100));sold='<div class="sold"><div class="bar"><i style="width:'+pc+'%"></i></div><small class="num">Vendidos: '+pr.promo.vend+' de '+pr.promo.cupo+'</small></div>'}
 return '<article class="card"><div style="position:relative"><button type="button" style="all:unset;display:block;cursor:pointer;width:100%" data-act="ver" data-id="'+p.id+'" aria-label="Ver '+esc(p.n)+'">'+artP(p)+'</button>'+
 '<div class="hov"><button type="button" data-act="fav-p" data-id="'+p.id+'" aria-pressed="'+fav+'" aria-label="Guardar en favoritos">'+ic('heart')+'</button><button type="button" data-act="ver" data-id="'+p.id+'" aria-label="Vista rápida">'+ic('eye')+'</button></div></div>'+
 '<div class="card-b"><button type="button" class="st" data-act="go" data-h="t-'+t.id+'">'+esc(t.n)+'</button><h3><button type="button" data-act="ver" data-id="'+p.id+'">'+esc(p.n)+'</button></h3>'+
 '<div class="rt">'+starsH(p.r)+'<span>('+p.rc+')</span><span>'+ic('clock')+(t.min>=120?'Mismo día':t.min+' min')+'</span></div>'+
 '<div class="card-f"><span class="pz num'+(pr.old?' of':'')+'">'+pesos(pr.p)+(pr.old?'<s>'+pesos(pr.old)+'</s>':'')+'</span><button class="add" type="button" data-act="add" data-id="'+p.id+'" aria-label="Agregar '+esc(p.n)+' al carrito"'+(off?' disabled':'')+'>'+ic('plus')+'</button></div>'+sold+'</div></article>';
}
function vendorCard(t){const c=tc(t);const np=S.prods.filter(p=>p.t===t.id).length;
 return '<button class="vd" type="button" data-act="go" data-h="t-'+t.id+'" style="--c:'+c+';--c2:'+(tclaro(t)?'var(--tinta)':c)+'"><span class="vd-h"><span class="vd-av">'+logoH(t)+'</span><span class="vd-open'+(t.abierto?'':' off')+'"><i></i>'+(t.abierto?'Abierto':'Cerrado')+'</span></span><span class="vd-b"><strong>'+esc(t.n)+'</strong><small>'+CAT[t.cat].n+' · '+np+' productos</small><span class="rt">'+starsH(t.r)+'<span>'+dec(t.r)+'</span><span>'+ic('pin')+esc(t.dir)+'</span></span></span></button>'}

