  '<div class="trust">'+[['moto','Domicilio desde $4.000','Hatillo, Chimí y San Martín'],['cash','Pagas al recibir','Efectivo, Nequi o fiado'],['shield','Reclamos atendidos','Si algo llega mal, te responden']].map(x=>'<div>'+ic(x[0])+'<span><strong>'+x[1]+'</strong><small>'+x[2]+'</small></span></div>').join('')+'</div></section>';
 let flash='';
 if(port){const p=PR(port.prod),t=T(port.t);flash='<section class="flash"><span class="fl-img" style="--c:'+tc(t)+'">'+(port.foto?'<img src="'+port.foto+'" alt="'+esc(p.n)+'">':(p.id==='asado'?PLATO:ic(p.i)))+'</span><div class="fl-tx"><h3>'+ic('bolt','fill')+'Oferta relámpago</h3><small>'+esc(port.titulo&&port.titulo!=='Oferta del día'?port.titulo:'Oferta del día')+' · '+esc(t.n)+'</small><span style="font-size:16px;font-weight:600">'+esc(p.n)+'</span><span class="fl-p num">'+pesos(port.precio)+'<s>'+pesos(p.p)+'</s></span><button class="btn b-sol" type="button" data-act="ver" data-id="'+p.id+'">Pedir la oferta</button></div>'+cdxH(port.hasta)+'</section>'}
