 const feat=activas.filter(x=>x!==port).slice(0,4).map(x=>PR(x.prod));
 const fsec='<section><div class="sec-h"><h2>Ofertas destacadas</h2><div class="r"><span style="font-size:13px;font-weight:600;color:#666">Terminan en</span>'+cdH(finDia())+'<button class="link" type="button" data-act="go" data-h="c-ofertas">Ver todas '+ic('arrow')+'</button></div></div><div class="hgrid">'+feat.map(hcard).join('')+'</div></section>';
 const duo='<section class="duo"><button class="dbn d-sol" type="button" data-act="go" data-h="c-campo"><span class="blob"></span><h3>Fresco del campo de Loba</h3><p>Coco, mango, panela y pescado de estanque, sacados hoy.</p><span class="btn b-tinta b-sm">Ver productos '+ic('arrow')+'</span><span class="ill"><span style="--c:var(--monte)">'+ic('coco')+'</span><span style="--c:var(--rio)">'+ic('pescado')+'</span></span></button>'+
  '<button class="dbn d-azul" type="button" data-act="go" data-h="t-deposito"><span class="blob"></span><h3>Para la casa y la obra</h3><p>Cemento, bloque y pintura con flete el mismo día.</p><span class="btn b-fucsia b-sm">Ir al depósito '+ic('arrow')+'</span><span class="ill"><span style="--c:var(--tinta)">'+ic('ladrillo')+'</span><span style="--c:var(--mango)">'+ic('pintura')+'</span></span></button></section>';
