 const vend='<section id="negocios"><div class="sec-h"><h2>Negocios en línea</h2><div class="r"><span style="font-size:13.5px;font-weight:600;color:#666">'+S.tiendas.filter(t=>t.abierto).length+' de '+S.tiendas.length+' abiertos ahora</span></div></div><div class="vendors">'+S.tiendas.map(vendorCard).join('')+'</div></section>';
 const nuevos='<section><div class="sec-h"><h2>Recién llegados</h2><button class="link" type="button" data-act="go" data-h="buscar">Ver todo '+ic('arrow')+'</button></div><div class="rail bs">'+S.prods.filter(p=>p.nuevo).map(p=>card(p)).join('')+'</div></section>';
 const rv=S.reviews.filter(r=>r.est===5).slice(0,4);
