 const sinCal=mine.filter(o=>o.e>=fin(o)&&!o.rech&&!o.cal);
 const deuda=S.user.fiados.reduce((a,f)=>a+f.v,0);
 const nav=[['resumen','home','Resumen'],['pedidos','receipt','Mis pedidos',act.length],['favoritos','heart','Favoritos'],['direcciones','pin','Direcciones'],['fiados','fiado','Mis fiados',S.user.fiados.length],['avisos','bell','Notificaciones',S.unread],['billetera','wallet','LobaPago'],['datos','user','Mis datos']];
