function pBalance(t,N){
 const sem=N.semana,ein=sem.reduce((a,d)=>a+d[1],0),eout=sem.reduce((a,d)=>a+d[2],0);
 const best=sem.reduce((a,d)=>d[1]>a[1]?d:a,sem[0]);const max=Math.max(...sem.map(d=>Math.max(d[1],d[2])));
 const ps=S.prods.filter(p=>p.t===t.id).slice().sort((a,b)=>b.v-a.v);
 const k=v=>v>=1e6?dec(v/1e6)+' M':Math.round(v/1000)+' mil';
 return head('Balance','Esta semana y este mes, en palabras claras.')+
 '<div class="box" style="background:var(--tinta);color:#fff;border-color:var(--tinta)"><p style="margin:0;font-size:18px;font-weight:600;max-width:60ch">Esta semana entraron <b style="color:var(--sol)">'+pesos(ein)+'</b>, salieron <b style="color:#FF8DB8">'+pesos(eout)+'</b> y te quedaron <b style="color:var(--lima)">'+pesos(ein-eout)+'</b>. Tu mejor día fue el <b>'+({Lun:'lunes',Mar:'martes','Mié':'miércoles',Jue:'jueves',Vie:'viernes','Sáb':'sábado',Dom:'domingo'})[best[0]]+'</b> con '+pesos(best[1])+'. Lo que más se vende: <b>'+esc(ps[0].n)+'</b> ('+Math.round(ps[0].v/4)+' esta semana).</p></div>'+
 '<div class="box"><h3>Entradas y salidas por día<span class="legend"><span><i style="background:var(--rio)"></i>Entró</span><span><i style="background:var(--fucsia)"></i>Salió</span><span><i style="background:var(--monte)"></i>Mejor día</span></span></h3><div class="bars">'+sem.map(d=>'<div class="col'+(d===best?' best':'')+'"><span class="v num">'+k(d[1])+'</span><div class="pair"><i class="in" style="height:'+(d[1]/max*100)+'%"></i><i class="out" style="height:'+(d[2]/max*100)+'%"></i></div><small>'+d[0]+'</small></div>').join('')+'</div></div>'+
 '<div class="g3 num"><div class="kpi"><small>Entró este mes</small><b>'+pesos(ein*4.2)+'</b><span>Aprox. 4 semanas</span></div><div class="kpi"><small>Salió este mes</small><b>'+pesos(eout*4.2)+'</b><span>Gastos anotados</span></div><div class="kpi gan"><small>Te quedó este mes</small><b>'+pesos((ein-eout)*4.2)+'</b><span>Ganancia</span></div></div>'+
 '<div class="box"><h3>Lo más vendido</h3><div class="tbl-w"><table class="tbl"><thead><tr><th>Producto</th><th class="r">Vendidos</th><th class="r">Precio</th></tr></thead><tbody>'+ps.map(p=>'<tr><td>'+esc(p.n)+'</td><td class="r num">'+p.v+'</td><td class="r num">'+pesos(p.p)+'</td></tr>').join('')+'</tbody></table></div></div>';
}
