document.addEventListener('click',e=>{
 const el=e.target.closest('[data-act]');
 if(!el){if(!e.target.closest('#deptMenu,.dept-btn'))closeDept();return}
 if(el.tagName==='INPUT'&&el.type==='checkbox'){A[el.dataset.act]&&A[el.dataset.act](el,e);return}
 const f=A[el.dataset.act];if(f){f(el,e)}
});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.name==='modo'&&co&&modalKind==='checkout'){co.modo=el.value;co.err='';rCheckout();const r=$('#o-modo-'+co.modo);if(r)r.focus();return}
 if(el.name==='pago'&&co&&modalKind==='checkout'){co.pago=el.value;rCheckout();const r=$('#o-pago-'+co.pago);if(r)r.focus();return}
 const k=el.dataset.chg;if(!k)return;
 if(k==='co-dirs'){co.dirI=+el.value;if(co.dirI>=0){const d=S.user.dirs[co.dirI];co.dir=d.d;co.zona=d.z}else co.dir='';rCheckout()}
 else if(k==='co-zona'){co.zona=el.value;rCheckout()}
 else if(k==='co-pers')co.personas=+el.value;
 else if(k==='co-hora')co.hora=el.value;
 else if(k==='co-comp'){co.comp=!!el.files[0];if(co.comp)toast('Pantallazo listo. Se envía con el pedido.')}
 else if(k==='b-max'){bus.max=+el.value;rerender()}
 else if(k==='b-ord'){bus.orden=el.value;rerender()}
 else if(k==='pp'){const p=PR(el.dataset.id);const old=p.p;p.p=Math.max(0,+el.value||0);logN(p.t,'Cambió precio de '+p.n+': '+pesos(old)+' → '+pesos(p.p));save();toast('Precio actualizado en tu tienda')}
 else if(k==='ps'){const p=PR(el.dataset.id);p.stock=Math.max(0,+el.value||0);save();toast('Disponibles actualizados')}
 else if(k==='pr-foto'){const f=el.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),s=Math.min(1,520/Math.max(img.width,img.height));c.width=img.width*s;c.height=img.height*s;c.getContext('2d').drawImage(img,0,0,c.width,c.height);try{fotoTmp=c.toDataURL('image/jpeg',.72)}catch(x){fotoTmp=null}$('#prPrev').innerHTML=fotoTmp?'<img class="prev-photo" src="'+fotoTmp+'" alt="Vista previa">':''};img.src=rd.result};rd.readAsDataURL(f)}
});
document.addEventListener('input',e=>{const k=e.target.dataset.inp;if(!k||!co)return;if(k==='co-dir')co.dir=e.target.value;if(k==='co-nota')co.nota=e.target.value;if(k==='co-cup')co.cup=e.target.value});
