(function upgrade(){
 if(S.zona==null)S.zona='cabecera';
 if(!S.hist)S.hist=['mojarra','coco','pan'];
 if(!S.cupAct)S.cupAct=[];
 if(!S.clipsV)S.clipsV=[];
 if(!S.recientes)S.recientes=['asado','suero','coco'];
 if(!S.wallet)S.wallet={saldo:48500,llave:'@maria.chimi',mov:[{d:'Recarga en Tienda Mi Pueblo',v:50000,f:'1 nov.'},{d:'Pago a Jugos La Ceiba',v:-1500,f:'Ayer'}]};
 if(!S.preguntas)S.preguntas=[
  {pid:'asado',q:'¿El asado trae gaseosa de litro o personal?',a:'Personal de 400 ml. Si la quiere de litro son $3.000 más.',f:'Ayer',autor:'Kevin'},
  {pid:'asado',q:'¿Lo pueden mandar sin ensalada?',a:'Claro, escríbalo en la nota del pedido.',f:'2 nov.',autor:'Ana'},
  {pid:'mojarra',q:'¿La mojarra es de río o de estanque?',a:null,f:'Hoy',autor:'Luis'},
  {pid:'suero',q:'¿Tienen suero de sabor para niños?',a:'Sí, de uva y de naranja, mismo precio.',f:'31 oct.',autor:'Rosa'},
  {pid:'cemento',q:'¿Cuánto vale el flete a San Martín?',a:null,f:'Hoy',autor:'Wilmer'}];
 const extra=[{id:'cu3',t:'jugos',code:'CEIBA15',pct:15,activo:true,usos:0},{id:'cu4',t:'panaderia',code:'PAN10',pct:10,activo:true,usos:0},{id:'cu5',t:'estanque',code:'PESCA8',pct:8,activo:true,usos:0}];
 extra.forEach(c=>{if(!S.cupones.some(x=>x.id===c.id))S.cupones.push(c)});
})();
function llega(t){
 const fee=t.zonas[S.zona];
 if(fee==null)return '<div class="llega gris">Solo para recoger en '+esc(t.dir.split(',')[0])+'</div>';
 if(!t.abierto)return '<div class="llega gris">Abre '+esc(t.horario.split('–')[0].trim())+'</div>';
 if(t.min<=20)return '<div class="llega"><span class="rapido">'+ic('bolt','fill')+'RÁPIDO</span> Llega en '+t.min+' min</div>';
 if(t.min<120)return '<div class="llega">Llega hoy en '+t.min+' min</div>';
 return '<div class="llega">Llega hoy</div>';
}
function topCat(p){const c=T(p.t).cat;const l=S.prods.filter(x=>T(x.t).cat===c).sort((a,b)=>b.v-a.v);return l.indexOf(p)===0}
function card(p,deal){
 const t=T(p.t),pr=precio(p),fav=S.session&&S.session.rol==='cliente'&&S.user.favP.includes(p.id),off=!p.disp||!t.abierto;
 let sold='';if(deal&&pr.promo){const pc=Math.min(100,Math.round(pr.promo.vend/pr.promo.cupo*100));sold='<div class="sold"><div class="bar"><i style="width:'+pc+'%"></i></div><small class="num">Vendidos: '+pr.promo.vend+' de '+pr.promo.cupo+'</small></div>'}
 return '<article class="card rv"><div style="position:relative"><button type="button" class="cimg" data-act="ver" data-id="'+p.id+'" aria-label="Ver '+esc(p.n)+'">'+artP(p)+'</button>'+
 '<div class="hov"><button type="button" data-act="fav-p" data-id="'+p.id+'" aria-pressed="'+fav+'" aria-label="Guardar en favoritos">'+ic('heart')+'</button><button type="button" data-act="qv" data-id="'+p.id+'" aria-label="Vista rápida">'+ic('eye')+'</button></div></div>'+
 '<div class="card-b">'+(topCat(p)?'<span class="mv">MÁS VENDIDO</span>':'')+'<h3><button type="button" data-act="ver" data-id="'+p.id+'">'+esc(p.n)+'</button></h3><button type="button" class="st" data-act="go" data-h="t-'+t.id+'">Por '+esc(t.n)+'</button>'+
 '<div class="rt">'+starsH(p.r)+'<span>('+p.rc+')</span></div>'+
 (pr.old?'<s class="old num">'+pesos(pr.old)+'</s>':'')+'<div class="card-f"><span class="pz num">'+pesos(pr.p)+(pr.old?'<span class="off-g">'+Math.round((1-pr.p/pr.old)*100)+'% OFF</span>':'')+'</span><button class="add" type="button" data-act="add" data-id="'+p.id+'" aria-label="Agregar '+esc(p.n)+' al carrito"'+(off?' disabled':'')+'>'+ic('plus')+'</button></div>'+llega(t)+sold+'</div></article>';
}

/* ---------- ruteo v4 ---------- */
function render(){
 const r=(location.hash||'#inicio').slice(1)||'inicio';RT=r;
 const ses=S.session;
 const isPanel=r==='panel'||r.indexOf('panel-')===0;
 document.body.classList.toggle('mode-panel',isPanel);
 closeDept();acClose();
 const home=()=>{history.replaceState(null,'','#inicio');RT='inicio';$('#app').innerHTML=vHome();afterHome()};
 if(EXT.ruta(r)){paint();updHeader();EXT.trasRender(r);return}
 if(isPanel){if(!ses||ses.rol==='cliente'){home();openLogin('negocio')}else $('#app').innerHTML=vPanel(r)}
 else if(r.indexOf('cuenta')===0){if(!ses||ses.rol!=='cliente'){home();openLogin('cliente')}else $('#app').innerHTML=vCuenta(r)}
 else if(r.indexOf('t-')===0&&T(r.slice(2)))$('#app').innerHTML=vTienda(r.slice(2));
 else if(r.indexOf('p-')===0&&PR(r.slice(2))){$('#app').innerHTML=vProd(r.slice(2));afterProd()}
 else if(r==='marcas')$('#app').innerHTML=vMarcas();
 else if(r==='cupones')$('#app').innerHTML=vCupones();
 else if(r==='historial')$('#app').innerHTML=vHist();
 else if(r==='buscar'||r.indexOf('c-')===0){if(r.indexOf('c-')===0){const c=r.slice(2);bus={q:'',cat:c==='ofertas'?'':c,sub:'',tiendas:[],max:0,ofertas:c==='ofertas',orden:'vendidos'};history.replaceState(null,'','#buscar');RT='buscar'}$('#app').innerHTML=vBuscar();afterBuscar()}
 else{$('#app').innerHTML=vHome();afterHome()}
 paint();updHeader();tickCD();setHH();
 const z=$('#zonaTx');if(z)z.textContent=ZN[S.zona];
 EXT.trasRender(r);
}
window.addEventListener('hashchange',()=>{const run=()=>{render();scrollTo(0,0)};if(document.startViewTransition&&!RM){try{const vt=document.startViewTransition(run);vt.ready.catch(()=>{});vt.finished.catch(()=>{})}catch(e){run()}}else run()});

