function relacionados(p,n){const c=T(p.t).cat;return S.prods.filter(x=>x.id!==p.id&&T(x.t).cat===c).concat(S.prods.filter(x=>x.id!==p.id&&T(x.t).cat!==c).sort((a,b)=>b.v-a.v)).slice(0,n)}
let hsT=null,hsI=0;
function hsTo(n){const h=$('#mlhero');if(!h)return;const s=h.querySelectorAll('.hs'),d=h.querySelectorAll('.hdots button');hsI=(n+s.length)%s.length;s.forEach((x,k)=>x.classList.toggle('on',k===hsI));d.forEach((x,k)=>{x.classList.toggle('on',k===hsI);const i=x.querySelector('i');if(i){i.style.animation='none';void i.offsetWidth;i.style.animation=''}})}
function afterHome(){hsI=0;clearInterval(hsT);hsT=setInterval(()=>{const h=$('#mlhero');if(!h){clearInterval(hsT);return}if(h.matches(':hover')||h.contains(document.activeElement))return;hsTo(hsI+1)},6000);tickCD()}

/* ---------- QR ---------- */
function qrSVG(seed){
 let h=0;for(const ch of seed)h=(h*31+ch.charCodeAt(0))>>>0;
 const N=25,r=()=>{h^=h<<13;h>>>=0;h^=h>>17;h^=h<<5;h>>>=0;return h%100};
 let rects='';
 const finder=(x,y)=>'<rect x="'+x+'" y="'+y+'" width="7" height="7" fill="#2D3277"/><rect x="'+(x+1)+'" y="'+(y+1)+'" width="5" height="5" fill="#fff"/><rect x="'+(x+2)+'" y="'+(y+2)+'" width="3" height="3" fill="#2D3277"/>';
 for(let y=0;y<N;y++)for(let x=0;x<N;x++){const inF=(x<8&&y<8)||(x>16&&y<8)||(x<8&&y>16);const mid=x>9&&x<15&&y>9&&y<15;if(!inF&&!mid&&r()<48)rects+='<rect x="'+x+'" y="'+y+'" width="1" height="1"/>'}
 return '<svg viewBox="-2 -2 29 29" class="qr" aria-hidden="true"><rect x="-2" y="-2" width="29" height="29" rx="2" fill="#fff"/><g fill="#2D3277">'+rects+'</g>'+finder(0,0)+finder(18,0)+finder(0,18)+'<rect x="10" y="10" width="5" height="5" rx="1.2" fill="#FFE600"/></svg>';
}

