function hist(id){S.hist=[id].concat(S.hist.filter(x=>x!==id)).slice(0,12);save()}
function distrib(p){const r=p.r,n=p.rc;const w=[Math.max(0,(r-4)*1.6+.1),.9-Math.abs(r-4.2)*.5,.08,.04,.03].map(x=>Math.max(.01,x));const s=w.reduce((a,b)=>a+b,0);return w.map(x=>Math.round(x/s*n))}
function resumenIA(p){
 const revs=S.reviews.filter(r=>r.pid===p.id||r.t===p.t);const txt=revs.map(r=>r.txt.toLowerCase()).join(' ');
 const pros=[],cons=[];
 const M=[[/calient/,'Llega caliente'],[/r[aá]pid|minutos|mismo d[ií]a/,'Entrega rápida'],[/fresc|fr[ií]o y|fr[ií]o\./,'Fresco'],[/sabros|mejor|como en casa|buen/,'Buen sabor'],[/precio/,'Buen precio'],[/complet/,'Pedido completo'],[/limpi/,'Bien empacado'],[/jugos/,'Jugoso']];
 M.forEach(m=>{if(m[0].test(txt))pros.push(m[1])});
 if(/demor|tard/.test(txt))cons.push('A veces se demora en horas pico');if(/falt/.test(txt))cons.push('Faltó algún acompañante');
 if(!pros.length)pros.push('Cumple lo que promete','Buena atención');
 const pct=Math.round(distrib(p)[0]/Math.max(1,p.rc)*100);
 return {pros:pros.slice(0,4),cons,txt:'Los compradores destacan que '+pros.slice(0,2).join(' y ').toLowerCase()+'. '+(cons.length?'Algunos mencionan que '+cons[0].toLowerCase()+'. ':'')+'El '+pct+'% le da 5 estrellas.',n:Math.max(p.rc,revs.length)};
}
