function mapaH(o){
 if(o.modo!=='domicilio'||o.rech||o.e<2)return '';
 const t=T(o.t),moving=o.e===3,done=o.e>=fin(o);
 const path='M40 150 C 90 150, 100 90, 150 92 S 230 60, 260 40';
 const eta=Math.max(1,Math.round((7000-(Date.now()-o.te))/1000*1.5));
 return '<div class="mapa"><svg viewBox="0 0 300 190" aria-label="Mapa del recorrido"><rect width="300" height="190" fill="#EEF3E8"/><path d="M-10 175 C 60 160, 120 185, 190 165 S 290 170, 310 150 L310 200 L-10 200z" fill="#B8D8F5"/><text x="210" y="184" font-size="9" fill="#4A7FB5" font-weight="700">Brazo de Loba</text>'+
 [30,75,120].map(y=>'<path d="M0 '+y+' H300" stroke="#fff" stroke-width="7"/>').join('')+[60,140,220].map(x=>'<path d="M'+x+' 0 V160" stroke="#fff" stroke-width="7"/>').join('')+
 '<path id="ruta'+o.n+'" d="'+path+'" fill="none" stroke="#3483FA" stroke-width="4" stroke-dasharray="7 6" stroke-linecap="round"/>'+
 '<g transform="translate(40 150)"><circle r="11" fill="#FF7733"/><text y="4" text-anchor="middle" font-size="9" fill="#fff" font-weight="800">'+t.ini+'</text></g><g transform="translate(260 40)"><circle r="11" fill="#00A650"/><path d="M-5 1l5-5 5 5v5h-10z" fill="#fff"/></g>'+
 (done?'':'<g>'+(moving&&!RM?'<animateMotion dur="7s" fill="freeze" path="'+path+'"/>':'')+'<g transform="'+(moving?'':'translate(40 150)')+'"><circle r="13" fill="#2D3277" stroke="#fff" stroke-width="3"/><path d="M-6 3a2 2 0 1 0 .1 0M6 3a2 2 0 1 0 .1 0M-6 3h5l3-6h-3M2-3l4 6" stroke="#FFE600" stroke-width="1.6" fill="none"/></g></g>')+
 '</svg><div class="mapa-f">'+(done?ic('check')+'<b>Entregado en tu casa</b>':moving?ic('moto')+'<b>El domiciliario va en camino</b><span class="muted">Llega en unos '+eta+' min</span>':ic('clock')+'<b>Preparando en '+esc(t.n)+'</b><span class="muted">Sale en pocos minutos</span>')+'</div></div>';
}

/* ---------- confeti y vuelo al carrito ---------- */
function confeti(){if(RM)return;const c=document.createElement('canvas');c.className='confeti';c.width=innerWidth;c.height=innerHeight;document.body.appendChild(c);const x=c.getContext('2d');const cols=['#FFE600','#3483FA','#00A650','#2D3277','#FF7733'];const ps=Array.from({length:140},()=>({x:innerWidth/2,y:innerHeight*.45,vx:(Math.random()-.5)*16,vy:-Math.random()*14-4,s:Math.random()*7+4,c:cols[Math.random()*5|0],r:Math.random()*6,vr:(Math.random()-.5)*.4}));let f=0;(function loop(){x.clearRect(0,0,c.width,c.height);ps.forEach(p=>{p.vy+=.45;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/3,p.s,p.s*.66);x.restore()});if(++f<110)requestAnimationFrame(loop);else c.remove()})()}
function volar(fromEl){
 if(RM||!fromEl)return;const tg=[...document.querySelectorAll('[data-act="carrito"]')].find(b=>b.offsetParent!==null);if(!tg)return;
 const a=fromEl.getBoundingClientRect(),b=tg.getBoundingClientRect();const d=document.createElement('div');d.className='fly';d.innerHTML=ic('cart');document.body.appendChild(d);
 const sx=a.left+a.width/2-20,sy=a.top+a.height/2-20,ex=b.left+b.width/2-20,ey=b.top+b.height/2-20;
 const an=d.animate([{transform:'translate('+sx+'px,'+sy+'px) scale(1)',opacity:1},{transform:'translate('+(sx+ex)/2+'px,'+(Math.min(sy,ey)-120)+'px) scale(1.1)',opacity:1,offset:.5},{transform:'translate('+ex+'px,'+ey+'px) scale(.3)',opacity:.6}],{duration:700,easing:'cubic-bezier(.5,0,.3,1)'});
 an.onfinish=()=>{d.remove();tg.classList.remove('bump');void tg.offsetWidth;tg.classList.add('bump')};
}

/* ---------- autocompletar ---------- */
function acClose(){const a=$('#ac');if(a)a.hidden=true}
function acShow(v){
 const a=$('#ac');if(!a)return;const q=v.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
 let h='';
 if(!q){h='<div class="ac-h">Búsquedas recientes</div>'+S.recientes.map(PR).filter(Boolean).map(p=>'<button type="button" data-act="ver" data-id="'+p.id+'">'+ic('history')+'<span>'+esc(p.n)+'</span></button>').join('')+'<button type="button" data-act="tono">'+ic('spark')+'<span>Pregúntale a <b>Toño</b> lo que necesitas</span></button>'}
 else{const n=s=>s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');const ps=S.prods.filter(p=>n(p.n+' '+p.sub).includes(q)).slice(0,6),ts=S.tiendas.filter(t=>n(t.n).includes(q)).slice(0,3);
  h=ps.map(p=>{const t=T(p.t);return '<button type="button" data-act="ver" data-id="'+p.id+'"><span class="th'+(tclaro(t)?' claro':'')+'" style="--c:'+tc(t)+';width:34px;height:34px">'+ic(p.i)+'</span><span>'+esc(p.n)+'<small>'+esc(t.n)+'</small></span><b class="num">'+pesos(precio(p).p)+'</b></button>'}).join('')+ts.map(t=>'<button type="button" data-act="go" data-h="t-'+t.id+'">'+ic('tienda')+'<span>'+esc(t.n)+'<small>Negocio · '+CAT[t.cat].n+'</small></span></button>').join('')+(ps.length+ts.length?'':'<div class="ac-h">Sin coincidencias. Prueba con Toño.</div>')+'<button type="button" data-act="tono" data-q="'+esc(v)+'">'+ic('spark')+'<span>Pedirle a Toño: "'+esc(v)+'"</span></button>'}
 a.innerHTML=h;a.hidden=false;paint(a);
}
document.addEventListener('focusin',e=>{if(e.target.id==='q')acShow(e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='q')acShow(e.target.value)});
document.addEventListener('click',e=>{if(!e.target.closest('.search'))acClose()},true);

/* ---------- clips (historias) ---------- */
let clipS=null;
function clipSlides(t){const ps=S.prods.filter(p=>p.t===t.id);const pr=S.promos.find(x=>x.t===t.id&&x.activo&&x.hasta>Date.now());const sl=[{k:'intro'}];if(pr)sl.push({k:'promo',pr});const top=ps.slice().sort((a,b)=>b.v-a.v)[0];if(top)sl.push({k:'top',p:top});return sl}
function openClip(id){const i=S.tiendas.findIndex(t=>t.id===id);clipS={ti:i,si:0,paused:false};rClip();}
function rClip(){
 const t=S.tiendas[clipS.ti],sl=clipSlides(t),s=sl[clipS.si];if(!S.clipsV.includes(t.id)){S.clipsV.push(t.id);save()}
 let body='';
 if(s.k==='intro')body='<div class="cs-c"><span class="cs-av" style="--c:'+tc(t)+'">'+logoH(t)+'</span><h3>'+esc(t.n)+'</h3><p>'+esc(t.desc)+'</p><span class="pill '+(t.abierto?'p-ok':'p-no')+'"><i></i>'+(t.abierto?'Abierto · '+t.horario:'Cerrado ahora')+'</span></div>';
 else if(s.k==='promo'){const p=PR(s.pr.prod);body='<div class="cs-c"><span class="hs-k">OFERTA DE HOY</span><span class="cs-big" style="--c:'+tc(t)+'">'+(s.pr.foto?'<img src="'+s.pr.foto+'" alt="">':ic(p.i))+'</span><h3>'+esc(p.n)+'</h3><p class="cs-p"><b class="num">'+pesos(s.pr.precio)+'</b> <s class="num">'+pesos(p.p)+'</s></p><button class="btn b-sol" type="button" data-act="clip-ver" data-id="'+p.id+'">Pedir la oferta</button></div>'}
 else{const p=s.p;body='<div class="cs-c"><span class="hs-k">LO MÁS PEDIDO</span><span class="cs-big" style="--c:'+tc(t)+'">'+ic(p.i)+'</span><h3>'+esc(p.n)+'</h3><p>'+p.v+' pedidos · '+starsH(p.r)+'</p><button class="btn b-sol" type="button" data-act="clip-ver" data-id="'+p.id+'">Ver producto</button></div>'}
 let ov=$('#clipOv');if(!ov){ov=document.createElement('div');ov.id='clipOv';ov.className='clipov';ov.setAttribute('role','dialog');ov.setAttribute('aria-label','Clips');document.body.appendChild(ov)}
 ov.innerHTML='<div class="cs" style="--bgc:'+tc(t)+'"><div class="cs-bars">'+sl.map((x,i)=>'<span><i class="'+(i<clipS.si?'full':i===clipS.si?'run':'')+'"></i></span>').join('')+'</div><div class="cs-top"><span class="cav" style="--c:'+tc(t)+'">'+logoH(t)+'</span><b>'+esc(t.n)+'</b><button type="button" class="cs-x" data-act="clip-x" aria-label="Cerrar">'+ic('x')+'</button></div>'+body+'<button type="button" class="cs-nav l" data-act="clip-p" aria-label="Anterior"></button><button type="button" class="cs-nav r" data-act="clip-n" aria-label="Siguiente"></button></div>';
 paint(ov);const run=ov.querySelector('.run');if(run)run.addEventListener('animationend',()=>clipNext());
 const cs=ov.querySelector('.cs');cs.addEventListener('pointerdown',e=>{if(e.target.closest('button:not(.cs-nav)'))return;cs.classList.add('paused')});cs.addEventListener('pointerup',()=>cs.classList.remove('paused'));cs.addEventListener('pointerleave',()=>cs.classList.remove('paused'));
}
function clipNext(){if(!clipS)return;const sl=clipSlides(S.tiendas[clipS.ti]);if(clipS.si<sl.length-1)clipS.si++;else if(clipS.ti<S.tiendas.length-1){clipS.ti++;clipS.si=0}else{clipClose();return}rClip()}
function clipPrev(){if(!clipS)return;if(clipS.si>0)clipS.si--;else if(clipS.ti>0){clipS.ti--;clipS.si=0}rClip()}
function clipClose(){clipS=null;const o=$('#clipOv');if(o)o.remove();if(RT==='inicio'){const y=scrollY;render();scrollTo(0,y)}}

/* ---------- asistente Toño ---------- */
let tono={open:false,msgs:[],busy:false};
const TK=[[/almuer|almorz|comida|hambre|asado|sancocho|bandeja|cena|comer/,'comida'],[/desayun|arepa|carima/,'rapida','Arepas y fritos'],[/perro|hamburg|salchi|noche/,'rapida','Perros y hamburguesas'],[/jugo|sed|raspao|refresc|salpic|corozo/,'rapida','Jugos y raspao'],[/fiebre|dolor|medic|suero|pañal|panal|beb|gripa|diarr|bloqueador|sol/,'farmacia'],[/mercado|arroz|aceite|tienda|gaseosa|aseo|huevo/,'tienda'],[/pan|torta|cumplea|bollo/,'tienda','Panadería'],[/cuaderno|colegio|[uú]til|fotocop|regalo|escolar/,'papeleria'],[/cemento|bloque|pintura|obra|constru|tubo/,'deposito'],[/coco|fruta|mango|panela|pescado|mojarra|cachama|bocachico/,'campo']];
function tonoPanel(){let p=$('#tono');if(!p){p=document.createElement('section');p.id='tono';p.className='tono';p.setAttribute('aria-label','Asistente Toño');document.body.appendChild(p)}
 p.innerHTML='<div class="tn-h"><span class="tn-av">'+ic('spark')+'</span><div><b>Toño</b><small>Tu asistente de compras · IA</small></div><button type="button" class="x" data-act="tono-x" aria-label="Cerrar asistente">'+ic('x')+'</button></div><div class="tn-m" id="tnM">'+tono.msgs.map(m=>'<div class="tm '+m.de+'">'+m.h+'</div>').join('')+(tono.busy?'<div class="tm bot typing"><i></i><i></i><i></i></div>':'')+'</div><div class="tn-chips">'+['Almuerzo por menos de $20.000','¿Qué hay en oferta hoy?','Algo para la fiebre','Arma un mercado para la semana','¿Dónde está mi pedido?'].map(c=>'<button type="button" data-act="tono-q" data-q="'+c+'">'+c+'</button>').join('')+'</div><form class="tn-f" data-form="tono"><label class="sr" for="tnIn">Escríbele a Toño</label><input id="tnIn" name="q" placeholder="Escribe lo que necesitas…" autocomplete="off"><button type="submit" aria-label="Enviar">'+ic('send')+'</button></form>';
 p.classList.toggle('on',tono.open);paint(p);const m=$('#tnM');if(m)m.scrollTop=m.scrollHeight;
}
function tonoOpen(q){tono.open=true;if(!tono.msgs.length)tono.msgs.push({de:'bot',h:'¡Hola'+(S.session&&S.session.rol==='cliente'?', '+esc(S.user.nombre.split(' ')[0]):'')+'! Soy <b>Toño</b>. Dime qué necesitas, para dónde y cuánto quieres gastar, y te busco las mejores opciones de los '+S.tiendas.length+' negocios.'});tonoPanel();$('#tonoFab').classList.add('off');if(q)tonoAsk(q);else setTimeout(()=>{const i=$('#tnIn');if(i)i.focus()},50)}
function tonoClose(){tono.open=false;tonoPanel();$('#tonoFab').classList.remove('off')}
function miniP(p){const t=T(p.t),pr=precio(p);return '<div class="tp"><button type="button" data-act="ver" data-id="'+p.id+'" class="tp-i'+(tclaro(t)?' claro':'')+'" style="--c:'+tc(t)+'" aria-label="Ver '+esc(p.n)+'">'+ic(p.i)+'</button><div><b>'+esc(p.n)+'</b><small>'+esc(t.n)+' · '+(t.min>=120?'hoy':t.min+' min')+'</small><span class="num">'+pesos(pr.p)+(pr.old?' <em>'+Math.round((1-pr.p/pr.old)*100)+'% OFF</em>':'')+'</span></div><button type="button" class="add" data-act="add" data-id="'+p.id+'" aria-label="Agregar '+esc(p.n)+'"'+(!p.disp||!t.abierto?' disabled':'')+'>'+ic('plus')+'</button></div>'}
function tonoAsk(q){
 tono.msgs.push({de:'yo',h:esc(q)});tono.busy=true;tonoPanel();
 setTimeout(()=>{tono.busy=false;const r=tonoBrain(q);tono.msgs.push({de:'bot',h:r});tonoPanel()},RM?100:850);
}
function tonoBrain(q){
 const s=q.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
 let zona=/chimi/.test(s)?'chimi':/san martin/.test(s)?'sanmartin':/cabecera|hatillo/.test(s)?'cabecera':null;
 let max=0;const mm=s.match(/(\d{1,3}(?:[.,]\d{3})+|\d+)\s*(mil|k|lucas)?/);if(mm){max=+mm[1].replace(/[.,]/g,'');if(mm[2]||max<1000)max*=1000}
 if(/pedido|donde esta|llega mi|mi orden/.test(s)){
  if(!S.session||S.session.rol!=='cliente')return 'Para ver tus pedidos necesito que entres a tu cuenta. <button class="btn b-sm b-fucsia" type="button" data-act="login" data-tab="cliente">Ingresar</button>';
  const a=S.orders.filter(o=>o.cli===S.user.usuario&&!o.rech&&o.e<fin(o)).sort((x,y)=>y.n-x.n)[0];
  return a?'Tu pedido <b>#'+a.n+'</b> de '+esc(T(a.t).n)+' va en: <b>'+pasos(a)[a.e][0]+'</b>. <button class="btn b-sm b-fucsia" type="button" data-act="orden" data-n="'+a.n+'">Ver seguimiento</button>':'No tienes pedidos en curso ahora. ¿Te busco algo?';
 }
 if(/mercado.*semana|semana|mercadito|arma/.test(s)){
  const ids=[['arroz',2],['mercadito',1],['panela',1],['gaseosa',2]];const tot=ids.reduce((a,x)=>a+precio(PR(x[0])).p*x[1],0);tono.bundle=ids;
  return 'Te armé un mercado básico para la semana con lo que hay hoy en el pueblo:<div class="tps">'+ids.map(x=>miniP(PR(x[0]))).join('')+'</div>Total aproximado: <b class="num">'+pesos(tot)+'</b> (2 arroz, mercadito, panela y 2 gaseosas). <button class="btn b-sm b-fucsia" type="button" data-act="tono-bundle">Agregar todo al carrito</button>';
 }
 if(/oferta|descuento|barato|rebaj/.test(s)&&!max){const l=S.promos.filter(x=>x.activo&&x.hasta>Date.now()).map(x=>PR(x.prod)).filter(Boolean).sort((a,b)=>(1-precio(b).p/b.p)-(1-precio(a).p/a.p)).slice(0,4);return 'Estas son las mejores ofertas de hoy, ordenadas por descuento:<div class="tps">'+l.map(miniP).join('')+'</div>'}
 let cat=null,sub=null;for(const k of TK){if(k[0].test(s)){cat=k[1];sub=k[2]||null;break}}
 let l=S.prods.filter(p=>{const t=T(p.t);if(cat&&t.cat!==cat)return false;if(sub&&p.sub!==sub)return false;if(max&&precio(p).p>max)return false;if(zona&&t.zonas[zona]==null)return false;return true});
 if(!cat){const w=s.split(/\s+/).filter(x=>x.length>3);l=S.prods.filter(p=>w.some(x=>(p.n+' '+p.d).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(x)));if(max)l=l.filter(p=>precio(p).p<=max)}
 l=l.filter(p=>p.disp&&T(p.t).abierto).sort((a,b)=>(b.r*20+b.v/10)-(a.r*20+a.v/10)).slice(0,3);
 if(!l.length)return 'No encontré algo que cumpla todo eso'+(max?' por menos de '+pesos(max):'')+(zona?' con domicilio a '+ZN[zona]:'')+'. Prueba subiendo el presupuesto o mira las <button class="link" type="button" data-act="go" data-h="c-ofertas">ofertas de hoy</button>.';
 tono.best={id:l[0].id,zona};
 const med=cat==='farmacia'?'<p class="tn-note">'+ic('alert')+'No soy médico. Antes de tomar algo, pregúntale al droguista por el chat del pedido.</p>':'';
 return 'Encontré '+l.length+' opción'+(l.length>1?'es':'')+(max?' por menos de <b class="num">'+pesos(max)+'</b>':'')+(zona?' con domicilio a <b>'+ZN[zona]+'</b>':'')+':<div class="tps">'+l.map(miniP).join('')+'</div>'+med+'¿Quieres que te prepare el pedido de <b>'+esc(l[0].n)+'</b>? Solo tienes que confirmar. <button class="btn b-sm b-fucsia" type="button" data-act="tono-pedir">'+ic('spark')+'Pídelo por mí</button>';
}
(function fab(){const b=document.createElement('button');b.id='tonoFab';b.type='button';b.className='tonofab';b.dataset.act='tono';b.setAttribute('aria-label','Abrir asistente Toño');b.innerHTML=ic('spark')+'<span>Pregúntale a Toño</span>';document.body.appendChild(b)})();

