function artP(p,big){const t=T(p.t),pr=precio(p);const foto=pr.promo&&pr.promo.foto;
 return '<span class="art-p'+(tclaro(t)?' claro':'')+'" style="--c:'+tc(t)+'">'+ic(p.i)+(foto?'<img class="ph" src="'+foto+'" alt="">':phH(p))+(pr.old&&!big?'<span class="star-off">-'+Math.round((1-pr.p/pr.old)*100)+'%</span>':(p.nuevo&&!big?'<span class="tag-new">NUEVO</span>':''))+(!t.abierto&&!big?'<span class="cerrado-tag">Cerrado ahora · abre '+t.horario.split('–')[0].trim()+'</span>':'')+'</span>';}
