/* ---------- categorías: transiciones con dirección y vista para celular ---------- */
function catKeys(){return [''].concat(CATS.map(c=>c.id)).concat(['ofertas'])}
function curKey(){return bus.ofertas?'ofertas':(bus.cat||'')}
function withVT(fn,dir){if(document.startViewTransition&&!RM){document.documentElement.dataset.vt=dir||'';try{const v=document.startViewTransition(fn);v.ready.catch(()=>{});v.finished.catch(()=>{}).finally(()=>{delete document.documentElement.dataset.vt})}catch(e){fn()}}else fn()}
function setCat(k){const ks=catKeys(),a=ks.indexOf(curKey()),b=ks.indexOf(k);if(a===b)return;
 const apply=()=>{bus.cat=k==='ofertas'?'':k;bus.ofertas=k==='ofertas';bus.sub='';bus.tiendas=[];if(RT==='buscar'){render();window.scrollTo(0,0)}else location.hash='buscar'};
 if(RT==='buscar')withVT(apply,b>a?'sig':'ant');else apply();
}
function filtrados(){
 const q=bus.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
 let l=S.prods.filter(p=>{const t=T(p.t);if(bus.cat&&t.cat!==bus.cat)return false;if(bus.sub&&p.sub!==bus.sub)return false;if(bus.tiendas.length&&!bus.tiendas.includes(p.t))return false;if(bus.ofertas&&!promoDe(p.id))return false;if(bus.max&&precio(p).p>bus.max)return false;if(q&&!(p.n+' '+p.d+' '+t.n+' '+p.sub).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))return false;return true});
 const o=bus.orden;l.sort((a,b)=>o==='menor'?precio(a).p-precio(b).p:o==='mayor'?precio(b).p-precio(a).p:o==='calificados'?b.r-a.r:o==='nuevos'?(b.nuevo-a.nuevo):b.v-a.v);return l}
const ORD=[['vendidos','Más vendidos'],['calificados','Mejor calificados'],['nuevos','Nuevos'],['menor','Precio: menor a mayor'],['mayor','Precio: mayor a menor']];
function vBuscar(){
 const l=filtrados(),o=bus.orden;
 const tit=bus.ofertas?'Ofertas de hoy':bus.cat?CAT[bus.cat].n:bus.q?'Resultados para "'+esc(bus.q)+'"':'Todos los productos';
 const ts=bus.cat?S.tiendas.filter(t=>t.cat===bus.cat):S.tiendas;
 const nf=bus.tiendas.length+(bus.max?1:0);
 const chips=[['','Todo','grid','var(--fucsia)']].concat(CATS.map(c=>[c.id,c.n.split(' y ')[0].replace('Comidas rápidas','Rápidas'),c.i,c.c])).concat([['ofertas','Ofertas','tag','var(--monte)']]);
 const k=curKey();
 const mbar='<div class="mcatbar only-m" id="mcatbar"><div class="mchips" role="tablist" aria-label="Categorías">'+chips.map(c=>'<button type="button" role="tab" class="mchip'+(c[0]===k?' on':'')+'" aria-selected="'+(c[0]===k)+'" data-act="m-cat" data-k="'+c[0]+'" style="--cc:'+c[3]+'"><span class="mci">'+ic(c[2])+'</span>'+c[1]+'</button>').join('')+'</div>'+
  (bus.cat?'<div class="msubs">'+['Todo'].concat(CAT[bus.cat].subs).map((s,i)=>'<button type="button" class="'+((i===0&&!bus.sub)||bus.sub===s?'on':'')+'" data-act="b-sub" data-s="'+(i===0?'':esc(s))+'">'+s+'</button>').join('')+'</div>':'')+'</div>';
 return '<div class="wrap"><div class="crumbs"><button type="button" data-act="go" data-h="inicio">Inicio</button>/<span>'+tit+'</span></div><div class="sec-h" style="margin-top:12px"><h2 class="vt-tit">'+tit+'</h2></div>'+mbar+
 '<div class="slayout" style="margin-top:0"><aside class="stack only-d" style="align-content:start">'+
 '<div class="sidebox"><h4>Categorías</h4><div class="fl"><button type="button" data-act="b-cat" data-c="" aria-pressed="'+(!bus.cat&&!bus.ofertas)+'">Todas</button>'+CATS.map(c=>'<button type="button" data-act="b-cat" data-c="'+c.id+'" aria-pressed="'+(bus.cat===c.id)+'">'+c.n+'</button>').join('')+'</div></div>'+
 (bus.cat?'<div class="sidebox"><h4>Tipo</h4><div class="fl"><button type="button" data-act="b-sub" data-s="" aria-pressed="'+(!bus.sub)+'">Todo</button>'+CAT[bus.cat].subs.map(s=>'<button type="button" data-act="b-sub" data-s="'+esc(s)+'" aria-pressed="'+(bus.sub===s)+'">'+s+'</button>').join('')+'</div></div>':'')+
 '<div class="sidebox"><h4>Negocios</h4>'+ts.map(t=>'<label class="ck"><input type="checkbox" data-act="b-t" data-id="'+t.id+'"'+(bus.tiendas.includes(t.id)?' checked':'')+'>'+esc(t.n)+'</label>').join('')+'</div>'+
 '<div class="sidebox"><h4>Precio máximo</h4><select data-chg="b-max" aria-label="Precio máximo"><option value="0">Cualquier precio</option>'+[5000,10000,20000,30000,50000].map(v=>'<option value="'+v+'"'+(bus.max===v?' selected':'')+'>Hasta '+pesos(v)+'</option>').join('')+'</select><label class="ck"><input type="checkbox" data-act="b-of"'+(bus.ofertas?' checked':'')+'>Solo ofertas de hoy</label></div></aside>'+
 '<div style="min-width:0"><div class="toolbar only-d"><b class="num">'+l.length+' productos</b><label style="display:flex;gap:8px;align-items:center;font-weight:700;font-size:14px">Ordenar por<select data-chg="b-ord">'+ORD.map(x=>'<option value="'+x[0]+'"'+(o===x[0]?' selected':'')+'>'+x[1]+'</option>').join('')+'</select></label></div>'+
 '<div class="mres only-m"><b class="num">'+l.length+' productos</b><span>'+ORD.find(x=>x[0]===o)[1]+'</span><span class="sw">'+ic('chevl')+'desliza para cambiar'+ic('chevr')+'</span></div>'+
 '<div id="catPane" class="catpane">'+(l.length?'<div class="grid-p">'+l.map(p=>card(p,bus.ofertas)).join('')+'</div>':'<div class="vacio">No encontramos productos con esos filtros. Prueba con otra palabra o quita filtros.</div>')+'</div></div></div>'+
 '<div class="mbar only-m"><button type="button" data-act="m-filtros">'+ic('menu')+'Filtrar'+(nf?' <b>'+nf+'</b>':'')+'</button><button type="button" data-act="m-orden">'+ic('chart')+'Ordenar</button></div></div>';
}
function afterBuscar(){
 const bar=$('.mchips');if(bar){const on=bar.querySelector('.on');if(on)bar.scrollTo({left:on.offsetLeft-bar.clientWidth/2+on.offsetWidth/2,behavior:'instant'})}
 const p=$('#catPane');if(!p)return;let x0=null,y0=0;
 p.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;x0=e.clientX;y0=e.clientY},{passive:true});
 p.addEventListener('pointerup',e=>{if(x0==null)return;const dx=e.clientX-x0,dy=e.clientY-y0;x0=null;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.6){const ks=catKeys(),i=ks.indexOf(curKey());const n=ks[Math.max(0,Math.min(ks.length-1,i+(dx<0?1:-1)))];setCat(n)}},{passive:true});
 p.addEventListener('pointercancel',()=>{x0=null});
}
