function afterProd(){afterProd0();const id=pv.id,f=FOTOS[id];if(!f)return;
 const img=new Image();img.onload=()=>{const th=document.querySelector('.thumbs'),gm=$('#gmain');if(!th||!gm||pv.id!==id)return;
  th.querySelectorAll('.th-b').forEach((b,i)=>b.dataset.n=i+1);gm.querySelectorAll('.gv').forEach(v=>v.classList.remove('on'));th.querySelectorAll('.th-b').forEach(b=>b.classList.remove('on'));
  th.insertAdjacentHTML('afterbegin','<button type="button" class="th-b on" data-act="pv-img" data-n="0" aria-label="Ver foto" style="--bg:#fff"><img src="'+img.src+'" alt=""></button>');
  gm.insertAdjacentHTML('afterbegin','<div class="gv on" style="--bg:#fff"><img src="'+img.src+'" alt="'+esc(PR(id).n)+'"></div>');
  const g=document.querySelector('.gal');if(g&&!g.querySelector('.credito'))g.insertAdjacentHTML('beforeend','<p class="credito">Foto: '+esc(f.a)+' · Unsplash</p>')};
 img.src='img/productos/'+id+'.jpg';
}

