let TV=null;
function vozLatina(){const vs=(window.speechSynthesis&&speechSynthesis.getVoices())||[];const es=vs.filter(v=>/^es/i.test(v.lang));
 const rank=v=>{const l=v.lang.toLowerCase().replace('_','-');let s=l==='es-co'?100:l==='es-mx'?90:l==='es-us'?80:l==='es-419'?75:/es-(ve|pe|cl|ar|ec|pa|cr|gt|hn|ni|sv|do|pr|bo|py|uy|cu)/.test(l)?70:l==='es-es'?20:40;if(/natural|online|neural|google/i.test(v.name))s+=8;return s};
 return es.sort((a,b)=>rank(b)-rank(a))[0]||null}
